def main():
    path = ROOT / "data/usmle-module-bank.json"
    bank = json.loads(path.read_text(encoding="utf-8"))
    questions = finalize(1, QUESTIONS, revision=2)
    module = next(m for m in bank["modules"] if m["moduleNumber"] == 1)
    module["questions"] = questions
    module["contentRevision"] = 2
    path.write_text(json.dumps(bank, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")
    print("Rebuilt Module 1 with 15 new revision-2 questions; other modules preserved.")


if __name__ == "__main__":
    main()
